using System;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AdditionalPurifyWithDrawbackOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/AdditionalPurifyWithDrawback Omen Data")]
public class AdditionalPurifyWithDrawbackOmenData : OnStartOfBattleOmenData
{
	[Header("Additional Purify With Drawback Omen Data")]
	[SerializeField]
	private int additionalPurifyAmount;

	[SerializeField]
	[HideIf("increasePurifyReceived")]
	private ZenithRingOmenData zenithRingOmenData;

	[SerializeField]
	[HideIf("increasePurifyReceived")]
	private OmenDescriptionIDReferences omenDescriptionIDReferences;

	[SerializeField]
	private bool increasePurifyReceived;

	[SerializeField]
	[ShowIf("increasePurifyReceived")]
	private IncreasePurifyReceivedByEnemiesOmenData increasePurifyReceivedByEnemiesOmenData;

	private Func<int, int> omenAdditionalPurifyAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAdditionalPurifyAction = (int purifyAmount) => purifyAmount + additionalPurifyAmount;
		if (increasePurifyReceived)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemyReceivePurifyModifierOmenActions.Add(omenAdditionalPurifyAction);
		}
		else
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifierOmenActions.Add(omenAdditionalPurifyAction);
		}
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		if (increasePurifyReceived)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemyReceivePurifyModifierOmenActions.Remove(omenAdditionalPurifyAction);
		}
		else
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifierOmenActions.Remove(omenAdditionalPurifyAction);
		}
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		if (increasePurifyReceived)
		{
			return increasePurifyReceivedByEnemiesOmenData.GetIncreasePurifyReceivedByEnemiesLocalizedString(additionalPurifyAmount) + "\n" + base.OmenConvertedDescription();
		}
		return zenithRingOmenData.GetDealAdditionalPurifyLocalizedDescription(additionalPurifyAmount).UppercaseFirst() + "\n" + base.OmenConvertedDescription();
	}
}
